head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > P > calendarValueType]<br/>DatePicker 컴포넌트의 UI 표시 포맷을 설정합니다.",
    "validation" : [
        "calendarValueType 속성값에 따라 표시되는 스핀 컬럼의 조합과 getValue()/setValue() 메소드의 값 포맷이 결정됩니다.",
        "DatePicker 컴포넌트의 UI 표시 포맷을 설정합니다. calendarValueType 속성값에 따라 표시되는 스핀 컬럼의 조합과 getValue()/setValue() 메소드의 값 포맷이 결정됩니다.",
        "'yearMonth' 설정 시 연, 월 컬럼을 표시합니다. 값 포맷은 'yyyyMM' (6자리) 입니다.",
        "'yearMonthDate' (default) 설정 시 연, 월, 일 컬럼을 표시합니다. 값 포맷은 'yyyyMMdd' (8자리) 입니다.",
        "'yearMonthDateTime' 설정 시 연, 월, 일, 오전/오후, 시, 분 컬럼을 표시합니다. 값 포맷은 'yyyyMMddHHmm' (12자리) 입니다.",
        "'hourMinute' 설정 시 오전/오후, 시, 분 컬럼을 표시합니다. 값 포맷은 'HHmm' (4자리) 입니다.",
        "'yearMonthDateTime' 과 'hourMinute' 는 오전/오후(ampm) 컬럼이 포함됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let calendarValueType = con_calendarValueType.getText();

    let properties = {
        calendarValueType : calendarValueType
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicDatePicker(cList);

    // calendarValueType 별로 setValue 포맷 보정 (createBasicDatePicker 기본 '20250101' 8자리)
    // yearMonth=6 / yearMonthDate=8 / yearMonthDateTime=12 / hourMinute=4
    if (calendarValueType === "yearMonth") {
        target1.setValue("202501");
    } else if (calendarValueType === "yearMonthDateTime") {
        target1.setValue("202501011030");
    } else if (calendarValueType === "hourMinute") {
        target1.setValue("1030");
    }
}



// 적용된 calendarValueType, 표시되는 스핀 컬럼 구성, getValue() 결과값 출력
scwin.getValueTypeInfo = function () {
    let valueType = target1.options.calendarValueType;
    let inputValue = target1.getValue();

    // validation: 미설정 시 기본값 'yearMonthDate' / 각 enum 값 설정 시 해당 값 적용
    wf_body_bottom.getObj("scwin").setReturnValue("[calendarValueType 적용값] '" + valueType + "'");
    // validation: yearMonth=6자리, yearMonthDate=8자리, yearMonthDateTime=12자리, hourMinute=4자리
    wf_body_bottom.getObj("scwin").setReturnValue("[getValue() 결과값 / 길이] '" + inputValue + "' / " + inputValue.length + "자리");

    // 스핀 컬럼 조합 (colTypeArr): 엔진의 makeColumns() 에서 구성됨
    // yearMonth → [year, month] / yearMonthDate → [year, month, date] / yearMonthDateTime → [year, month, date, ampm, hour, minute] / hourMinute → [ampm, hour, minute]
    let colTypeArr = target1.colTypeArr || [];
    wf_body_bottom.getObj("scwin").setReturnValue("[스핀 컬럼 수 / 컬럼 조합] " + colTypeArr.length + "개 / [" + colTypeArr.join(', ') + "]");

    // 오전/오후(ampm) 컬럼 포함 여부: yearMonthDateTime, hourMinute 만 포함
    let hasAmpm = !!(target1.colTypeObj && target1.colTypeObj.hasOwnProperty('ampm'));
    wf_body_bottom.getObj("scwin").setReturnValue("[오전/오후(ampm) 컬럼 포함 여부] " + (hasAmpm ? "포함됨" : "포함되지 않음"));
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getValueTypeInfo();
}
